/**
 * @param {Object} scene reference to phaser 3 stage/state
 * @param {Object} myStats - a struct with player battle data
 * @param {Object} targetStats - struct with skill target battle data
 * @param {Array[boolean]} answers - array containing correct or incoorectg results of math puzzle
 * @param {*} onSequenceComplete - callback that occurs when player has returned to starting spot
 */
const defenseSequence = (scene, myStats, targetStats, answers, onSequenceComplete) => {
    const player = myStats.sprite;
    const target = targetStats.sprite;

    console.log(myStats, targetStats);
    
    let direction = "Right";
    let oppositeDirection = "Left";
    if (player.x > target.x){
        direction = "Left";
        oppositeDirection = "Right";
    }
    let hitDirection = direction === "Left" ? 1 : -1;
    let abilityName = "spellBack";

    player.once("engage", (answers, enemy, enemyStats) => {
        player.play("run" + direction + myStats.key);
        scene.tweens.add({
            targets: player,
            x: enemy.x + (player.width + (player.width * 0.25)) * -hitDirection,
            y: enemy.y,
            ease: 'LinearIn', 
            duration: 1000,
            repeat: 0,
            onComplete: () => {
                player.emit("defend", answers, enemy, enemyStats)
            }
        });
    }, scene);

    player.once("defend", (answers, enemy, enemyStats) => {
        
        player.play(abilityName + myStats.key);
        player.anims.chain("run" + oppositeDirection + myStats.key);
        player.on("animationcomplete-" + abilityName + myStats.key, () => {
            let defenseMod = 0.05;
            answers.forEach((ans) => {
                if (ans){
                    defenseMod += .05;
                }
            });
            let defenseBonus = Math.ceil(myStats.def * defenseMod);
            
            myStats.statBuffs.def = defenseBonus;
            myStats.status.defending = true;
            if (enemyStats !== myStats){
                console.log("youre protected!");
                enemyStats.protectors.push(myStats);
                enemyStats.status.protected = true;
                myStats.protectees = enemyStats;
            }
            else {
                console.log("cant proctect yourself!!", myStats.name, enemyStats.name)
            }
            
            
            console.log("defense increased by:", defenseBonus);


        });

        player.once("animationstart-run" + oppositeDirection + myStats.key, () => {
            player.emit("disengage", myStats);
        });
    }, scene);

    player.once("disengage", (stats) => {
        player.removeListener("animationcomplete-" + abilityName + myStats.key);
        scene.tweens.add({
            targets: player,
            x: stats.originX,
            y: stats.originY,
            ease: 'LinearIn', 
            duration: 500,
            repeat: 0,
            onComplete: () => {
                player.play("walk" + direction + stats.key);
                player.emit("walk" + direction + stats.key)
                if (typeof onSequenceComplete === "function"){
                    onSequenceComplete();
                }
            }
        });
    })

    player.once("walk" + direction + myStats.key, () => {
        
    }) 

    //console.log(target, myStats)
    player.emit("engage", answers, target, targetStats);
}

export default defenseSequence;