//13 x 21
let LPCAnimations = (scene, sheet) => {
    
    let fps = 8;

    let getFrames = (row, col, amount) => {
        let xTiles = 13;
        let yTiles = 21;
        let start = (row * xTiles) + col
        let end = start + amount;
        let result = []
        for (let i = 0; i < amount; i++){
            result.push(start + i);
        }

        return result;
    }

    scene.anims.create({
        key: 'spellBack' + sheet,
        frames: scene.anims.generateFrameNumbers(sheet, { frames: getFrames(0,0,7) }),
        frameRate: fps,
        repeat: 0
    });

    scene.anims.create({
        key: 'spellLeft' + sheet,
        frames: scene.anims.generateFrameNumbers(sheet, { frames: getFrames(1,0,7) }),
        frameRate: fps,
        repeat: 0
    });

    scene.anims.create({
        key: 'spellFront' + sheet,
        frames: scene.anims.generateFrameNumbers(sheet, { frames: getFrames(2,0,7) }),
        frameRate: fps,
        repeat: 0
    });

    scene.anims.create({
        key: 'spellRight' + sheet,
        frames: scene.anims.generateFrameNumbers(sheet, { frames: getFrames(3,0,7) }),
        frameRate: fps,
        repeat: 0
    });

    scene.anims.create({
        key: 'attack1Back' + sheet,
        frames: scene.anims.generateFrameNumbers(sheet, { frames: getFrames(4,0,8) }),
        frameRate: fps * 3,
        repeat: 0
    });

    scene.anims.create({
        key: 'attack1Left' + sheet,
        frames: scene.anims.generateFrameNumbers(sheet, { frames: getFrames(5,0,8) }),
        frameRate: fps * 2,
        repeat: 0
    });

    scene.anims.create({
        key: 'attack1Front' + sheet,
        frames: scene.anims.generateFrameNumbers(sheet, { frames: getFrames(6,0,8) }),
        frameRate: fps * 2,
        repeat: 0
    });

    scene.anims.create({
        key: 'attack1Right' + sheet,
        frames: scene.anims.generateFrameNumbers(sheet, { frames: getFrames(7,0,8) }),
        frameRate: fps * 2,
        repeat: 0
    });

    scene.anims.create({
        key: 'walkBack' + sheet,
        frames: scene.anims.generateFrameNumbers(sheet, { frames: getFrames(8,0,9) }),
        frameRate: fps,
        repeat: -1
    });

    scene.anims.create({
        key: 'walkLeft' + sheet,
        frames: scene.anims.generateFrameNumbers(sheet, { frames: getFrames(9,0,9) }),
        frameRate: fps,
        repeat: -1
    });

    scene.anims.create({
        key: 'walkFront' + sheet,
        frames: scene.anims.generateFrameNumbers(sheet, { frames: getFrames(10,0,9) }),
        frameRate: fps,
        repeat: -1
    });

    scene.anims.create({
        key: 'walkRight' + sheet,
        frames: scene.anims.generateFrameNumbers(sheet, { frames: getFrames(11,0,9) }),
        frameRate: fps,
        repeat: -1
    });

    scene.anims.create({
        key: 'attack2Back' + sheet,
        frames: scene.anims.generateFrameNumbers(sheet, { frames: getFrames(12,0,6) }),
        frameRate: fps * 4,
        repeat: 0
    });

    scene.anims.create({
        key: 'attack2Left' + sheet,
        frames: scene.anims.generateFrameNumbers(sheet, { frames: getFrames(13,0,6) }),
        frameRate: fps * 4,
        repeat: 0
    });

    scene.anims.create({
        key: 'attack2Front' + sheet,
        frames: scene.anims.generateFrameNumbers(sheet, { frames: getFrames(14,0,6) }),
        frameRate: fps * 4,
        repeat: 0
    });

    scene.anims.create({
        key: 'attack2Right' + sheet,
        frames: scene.anims.generateFrameNumbers(sheet, { frames: getFrames(15,0,6) }),
        frameRate: fps * 4,
        repeat: 0
    });

    scene.anims.create({
        key: 'attack3Back' + sheet,
        frames: scene.anims.generateFrameNumbers(sheet, { frames: getFrames(16,0,13) }),
        frameRate: fps,
        repeat: 0
    });

    scene.anims.create({
        key: 'attack3Left' + sheet,
        frames: scene.anims.generateFrameNumbers(sheet, { frames: getFrames(17,0,13) }),
        frameRate: fps,
        repeat: 0
    });

    scene.anims.create({
        key: 'attack3Front' + sheet,
        frames: scene.anims.generateFrameNumbers(sheet, { frames: getFrames(18,0,13) }),
        frameRate: fps,
        repeat: 0
    });

    scene.anims.create({
        key: 'attack3Right' + sheet,
        frames: scene.anims.generateFrameNumbers(sheet, { frames: getFrames(19,0,13) }),
        frameRate: fps,
        repeat: 0
    });

    scene.anims.create({
        key: 'deathFront' + sheet,
        frames: scene.anims.generateFrameNumbers(sheet, { frames: getFrames(20,0,6) }),
        frameRate: fps,
        repeat: 0
    });




    ///
    ///Extra Custom Animations
    scene.anims.create({
        key: 'runBack' + sheet,
        frames: scene.anims.generateFrameNumbers(sheet, { frames: getFrames(8,0,9) }),
        frameRate: fps * 10,
        repeat: -1
    });

    scene.anims.create({
        key: 'runLeft' + sheet,
        frames: scene.anims.generateFrameNumbers(sheet, { frames: getFrames(9,0,9) }),
        frameRate: fps * 10,
        repeat: -1
    });

    scene.anims.create({
        key: 'runFront' + sheet,
        frames: scene.anims.generateFrameNumbers(sheet, { frames: getFrames(10,0,9) }),
        frameRate: fps * 10,
        repeat: -1
    });

    scene.anims.create({
        key: 'runRight' + sheet,
        frames: scene.anims.generateFrameNumbers(sheet, { frames: getFrames(11,0,9) }),
        frameRate: fps * 10,
        repeat: -1
    });
}

export default LPCAnimations;