import LPC from "src/tools/lpcSpriteAnimations.js";
import SkeletonDagger from "src/assets/skeletonDagger.png";
import SkeletonSpear from "src/assets/skeletonArmorShieldSpear.png";
import AttackSequence from "src/tools/attackSequence.js";
import DefendSequence from "src/tools/defenseSequence.js";
import Lifebar from "src/tools/lifebar.js"

class BattleTest extends Phaser.Scene {

    constructor () {
        super("battleTest");
    }

    init(data) {}
    preload () {
        this.load.spritesheet('SD', SkeletonDagger, { frameWidth: 64, frameHeight: 64 });
        this.load.spritesheet('SS', SkeletonSpear, { frameWidth: 64, frameHeight: 64 });
    }
    create (data)  {
        this.battleParticpants = [];
        this.latestID = 0;
        data.players.forEach((playerData) => {
            this.initParticipant(playerData);
        });
        
        this.abilityList = {
            attack: AttackSequence,
            defend: DefendSequence,
            magic: () => {
                console.log("this is magic!")
            },
            special: () => {
                console.log("this is a special!")
            },
        };
        
        let turns = this.calculateTurns(100, this.battleParticpants);
        this.events.on("nextTurn", () => {
            this.nextTurn(turns, this.battleParticpants)
        });

        this.events.emit("nextTurn");
    }

    nextTurn(turns, participants){
        if (turns.length === 0){
            turns = this.calculateTurns(100, this.battleParticpants);
            console.log("Turns have been refreshed!")
        }
        let unitID = turns.splice(0, 1);
        let unit = participants[unitID];
        if (!unit.status.alive){
            console.log(unit.name, "is fallen, moving on.")
            this.events.emit("nextTurn");
        }
        else if (unit.mainPlayer){
            let main = this.scene.get("main");
            main.events.emit("playerTurn", unit, participants);
            this.events.once("action", (action, targets, results) => {
                console.log("action targets", targets);
                this.abilityList[action](this, unit, targets[0], results, () => {
                    this.events.emit("nextTurn");
                });
            })
        }
        else {
            //default to basic attack for now
            this.traceEnemy(unitID, participants, (attacker, enemy) => {
                //in the future cpu answers should be based on ai
                let cpuAnswers = [true];
                AttackSequence(this, attacker, enemy, cpuAnswers, () => {
                    this.events.emit("nextTurn");
                })
            })
        }
    }

    initParticipant(data) {
        data.id = this.latestID++;
        LPC(this, data.key);

        let player = this.add.sprite(data.originX, data.originY, data.key);
        player.setScale(2, 2);
        player.play(data.move + data.directionFace + data.key);
  
        data.lifebar = Lifebar(this, player, 100, 5);
        data.sprite = player;

        player.once("fallen", () => {
            data.status.alive = false;
            data.lifebar.destroy();
            data.sprite.destroy();
        })
        player._battleData = data;
        this.battleParticpants.push(data);
    }

    traceEnemy(attackerID, participants, call) {
        let attacker = participants[attackerID];
        for (let i = 0; i < participants.length; i++){
            let victim = participants[i];
            if (!victim.status.alive){
                continue;
            }
            if (attacker.team !== victim.team){
                call(attacker, victim);
                break;
            }
        }
    }

    calculateTurns(amount, participants){
        let turns = [];
        let timeGoal = 1000;
        while (turns.length < amount){
            for (let i = 0; i < participants.length; i++){
                if (turns.length > amount){
                    break;
                }
                let ply = participants[i];
                ply.turnTime += ply.speed;
                if (ply.turnTime >= timeGoal){
                    ply.turnTime -= timeGoal;
                    turns.push(ply.id);
                }
            }
        }
        return turns
    }

    hitText(x, y, distanceX, distanceY, message){
        let variance = Math.floor(Math.random() * 10);
        variance = Math.random() > 0.49 ? variance : -variance;
        y += variance;
        x += variance;
        let scene = this;
        let textData = {
            text: message,
            font: "retro",
            add: true,
            size: 25
        }
        let textSpr = scene.make.bitmapText(textData);
        textSpr.x = x;
        textSpr.y = y;
        let duration = 600;
        
        let quickFade = () => {
            scene.tweens.add({
                targets: textSpr,
                alpha: 0,
                x: textSpr.x + distanceX,
                y: textSpr.y + distanceY,
                ease: 'Sine.Out',
                duration: 1000,
                delay: 0,
                repeat: 0,
                yoyo: false,
                repeatDelay: 0,
            });
            //rt.clear("damageText")
        }
        
        scene.tweens.add({
            targets: textSpr,
            x: textSpr.x + -distanceX,
            ease: 'Sine.Out',
            duration: duration,
            delay: 0,
            repeat: 0,
            yoyo: false,
            repeatDelay: 0,
            onComplete: quickFade
        });

        scene.tweens.add({
            targets: textSpr,
            y: textSpr.y - 20,
            ease: 'Cubic.easeInOut',
            duration: duration * 0.5,
            repeat: 0,
            yoyo: true,
        });

        //Experimental bitmap text fade
        // let rt = scene.add.renderTexture(x, y, 175, 100); 
        // rt.saveTexture("damageText");
        // rt.draw(textSpr, 0, 0);
        // console.log(rt);
        // let sprinkles = scene.add.particles("damageText");
        // let emitter = sprinkles.createEmitter({
        //     ease: 'Sine.easeIn',
        //     x: textSpr.x,
        //     y: textSpr.y,
        //     lifespan: 500,
        //     alpha: {start: 0.25, end: 0},
        //     follow: textSpr,
        //     followOffset: {x: -50, y: textSpr.y - 200}
        // });
        // rt.y = -150;
    }
    update(time, delta) {}

}

export default BattleTest;