//get configuration
import conf from "src/config/data.js";

import choiceUI from "src/tools/choiceButton.js";
import choiceData from "src/config/formulaChoiceData.js";
import EQ from "src/tools/equationGenerator.js";
import ResultEffect from "src/tools/resultIconEffect.js";
import vibrateEffect from "src/tools/vibrateEffect.js";
import Timebar from "src/tools/timebar.js";

class Puzzle extends Phaser.Scene {

    constructor () {
        super("puzzle");
    }

    init(data) {}
    preload () {}
    create (data)  {
        let gameVolume = 0.3
        this.correctSFX = this.sound.add('correctAnswer',{
            volume: gameVolume - 0.25,
        });
        this.incorrectSFX = this.sound.add('incorrectAnswer');
        this.mark = this.add.image(0, 0, "currentMark");
        let pulseTween = this.tweens.add({
            targets: this.mark,
            displayWidth: this.mark.displayWidth + 15,
            displayHeight: this.mark.displayHeight + 25,
            ease: 'Bounce.InOut',
            duration: 100,
            repeat: -1,
            yoyo: true,
            repeatDelay: 0,
        });

        let challengeEvents = new Phaser.Events.EventEmitter();
        let currentEqauationButtons;
        let currentTimerGUI;
        let currentTime;

        challengeEvents.on("newChallenge", () => {
            this.chosenAnswers = [];
            this.resultIcons = this.add.group();
            this.presentOptions = this.add.group();
            let challenge;
            let challengeTime = 1000;

            switch (data.level){
                case 1:
                    challenge = this.challenge1(data.time);
                break;
        
                case 2:
                    challenge = this.challenge2(data.time);
                break;

                case 3:
                    challenge = this.challenge3(data.time);
                break;

                case 4:
                    challenge = this.challenge4(data.time);
                break
            }

            currentEqauationButtons = challenge.eButtons;
            currentTimerGUI = challenge.timer[0];
            currentTime = challenge.timer[1];
        }, this);
        
        challengeEvents.on("getResults", () => {
            //clean up all sprites and previous results here
            //console.log(this.chosenAnswers)
            currentTime.remove();
            currentTime = null;
            if (Array.isArray(this.presentOptions)) {
                this.presentOptions.forEach((ui) => {
                    ui.destroy(true);   
                });
                this.presentOptions = null;
            }
            
            currentEqauationButtons.forEach((button) => {
                button.destroy(true);
            });
            currentTimerGUI.destroy(true);
            currentEqauationButtons = null;
            
            
            if (this.chosenAnswers.length > 0) {
                ResultEffect(this, this.resultIcons, () => {
                    this.events.emit('completed', this.chosenAnswers);
                });
            }
            else {
                this.events.emit('completed', this.chosenAnswers);
            }            
        }, this)


        challengeEvents.emit("newChallenge");
        this.challenge = challengeEvents;
    }

    challenge1(time) {
        //time is 100 units a second
         //collection of answer result icons
        let startX = 250;
        let equationNodes = EQ(2, "+", 1, 10);
        let equationButtons = equationNodes.map((node, dex) => {
            return choiceUI(this, startX + (75 * dex), 150, node);
        });

        this.displayPresentOptions(equationNodes, equationButtons, 0)
        let timer = Timebar(this, 375, 25, 50, 2.5, time, () => {
            this.challenge.emit("getResults");
        });

        return {
            eButtons: equationButtons,
            timer: timer
        };
    }

    challenge2(time) {
        //time is 100 units a second
        console.log("chally 2!!!", time);
        let startX = 150;
        let equationNodes = EQ(3, "+", 1, 10);
        let equationButtons = equationNodes.map((node, dex) => {
            return choiceUI(this, startX + (75 * dex), 150, node);
        });

        this.displayPresentOptions(equationNodes, equationButtons, 0)
        let timer = Timebar(this, 375, 25, 50, 2.5, time, () => {
            this.challenge.emit("getResults");
        });

        return {
            eButtons: equationButtons,
            timer: timer
        };
    }

    challenge3(time) {
        //time is 100 units a second
        let startX = 250;
        let equationNodes = EQ(2, "+", 1, 10);
        let unknowns = 1;
        let unknownNodes = [];
        for (let i = 0; i < unknowns; i++){
            let place = Math.floor(Math.random() *equationNodes.length);
            unknownNodes.push(place);
        }
        let equationButtons = equationNodes.map((node, dex) => {
            unknownNodes.forEach((uNode) => {
                if (uNode === dex){
                    node = "?";
                }
            });
            return choiceUI(this, startX + (75 * dex), 150, node);
        });
        
        this.displayPresentOptions(equationNodes, equationButtons, 0);
        let timer = Timebar(this, 375, 25, 50, 2.5, time, () => {
            this.challenge.emit("getResults");
        });

        return {
            eButtons: equationButtons,
            timer: timer
        };
    }

    challenge4(time) {
        //time is 100 units a second
        let startX = 150;
        let equationNodes = EQ(3, "+", 1, 10);
        let unknowns = 1;
        let unknownNodes = [];
        for (let i = 0; i < unknowns; i++){
            let place = Math.floor(Math.random() *equationNodes.length);
            unknownNodes.push(place);
        }
        let equationButtons = equationNodes.map((node, dex) => {
            unknownNodes.forEach((uNode) => {
                if (uNode === dex){
                    node = "?";
                }
            })
            return choiceUI(this, startX + (75 * dex), 150, node);
        });

        this.displayPresentOptions(equationNodes, equationButtons, 0);
        let timer = Timebar(this, 375, 25, 50, 2.5, time, () => {
            console.log("we gettin em'")
            this.challenge.emit("getResults");
        });

        return {
            eButtons: equationButtons,
            timer: timer
        };
    }

    displayPresentOptions (nodes, buttons, occurance = 0) {
        if (occurance >= nodes.length){
            console.log("present results")
            this.challenge.emit("getResults");
            return
        }
        let answerButton = buttons[occurance].children.entries[0];
        let answerText   = buttons[occurance].children.entries[1];
        let markX = answerButton.x; 
        let markY = answerButton.y - 75;
        this.mark.x = markX;
        this.mark.y = markY;

        let correctPlacing = Math.floor(Math.random() * 4);
        let correctAnswer  = nodes[occurance];
        let guessNodes = [0,0,0,0];

        let optionEvents = new Phaser.Events.EventEmitter();
        let clearEvent = "clearGuesses";

        guessNodes = guessNodes.map((no, dex) => {
            let randy;
            //check if this is predestined position for answer
            if (dex === correctPlacing){
                randy = correctAnswer;
            }
            else {
                let min = correctAnswer > 10 ? 10 : 0;
                let adjust = correctAnswer > 10 ? 20 : 10;
                randy = Math.floor(Math.random() * adjust);
                randy = Math.max(randy, min);
                if (randy === correctAnswer){
                    randy = randy - 1;
                }
            }           

            return randy;
        });

        this.presentOptions = guessNodes.map((node, dex) => {
            let markX = answerButton.x; 
            let markY = answerButton.y - 75;
            let green = 0x00ff00;
            let red   = 0xff0000;
            let selectedAnswer = false
            let checkIfCorrect = (guess) => {
                let answerResult = this.add.image(answerButton.x, answerButton.y - 35, "correctImg");
                if (guess === correctAnswer){
                    answerResult.tint = green;
                    answerResult._tintReuse = green;
                    answerButton.tint = green;
                    selectedAnswer = true;
                    this.correctSFX.play();
                    vibrateEffect(this, answerButton, true, false)             
                }
                else {
                    answerResult.setTexture("incorrectImg");
                    answerResult.tint = red;
                    answerResult._tintReuse = red;
                    answerButton.tint = red;
                    this.incorrectSFX.play();
                    vibrateEffect(this, answerButton, false, true)  
                }
                answerText.text = correctAnswer;
                this.resultIcons.add(answerResult);
                this.chosenAnswers.push(selectedAnswer)
                optionEvents.emit(clearEvent);
            }

            let option = choiceUI(this, 150 + (150 * dex), 250, node, checkIfCorrect);
            option.scaleXY(1.010, 1.010);
            let optionSpr = option.children.entries[0];
            optionSpr.tint = 0xdddd00;
            let optionText = option.children.entries[1];
            let doubleMod = Number(optionText.text) > 9 ? 15 : 0;
            optionText.x = optionText.x - (15 + doubleMod);
            optionText.y = optionText.y - 15;
            return option
        });
        
        optionEvents.once(clearEvent, () => {
            this.presentOptions.forEach((ui) => {
                ui.destroy(true);
            });
            this.displayPresentOptions(nodes, buttons, occurance + 1);
        }, this);
    }

    update(time, delta) {}

}

export default Puzzle