const Effect = (scene, icons, whenFinished) => {
    let floatTime = 250;
    let fadeTime = 250;
    let finishAction = (tween, targets) => {
        scene.tweens.add({
            targets: targets,
            alpha: 0,
            ease: 'Sine.easeIn',
            duration: fadeTime,
            scaleX: 10,
            scaleY: 0.1,
            delay: 0,
            repeat: 0,
        })
    }
    let totalIcons = icons.children.entries.length;
    icons.children.entries.forEach((result, dex) => {
        let shadowMove = scene.add.particles(result.texture.key);
        let shadowEmitter = shadowMove.createEmitter({
            //blendMode: Phaser.BlendModes.Add,
            alpha: {start: .25, end: 0},
            tint: result._tintReuse,
            ease: 'Sine.easeIn',
            x: result.x,
            y: result.y,
            lifespan: 1000,
            follow: result,
            followOffset: {x: -result.x, y: -result.y}
        });

        let sprinkles = scene.add.particles("incorrectImg");
        let emitter = sprinkles.createEmitter({
            alpha: 1,
            ease: 'Sine.easeIn',
            x: {min: result.x - 10, max: result.x + 10},
            y: result.y,
            lifespan: floatTime * 4,
            speedX: {min: -15, max: 15},
            scale: {start: 0.2, end: 0.025},
            speedY: {min: 15, max: 50},
            follow: result,
            followOffset: {x: -result.x, y: -result.y + 5}
        });

        scene.tweens.add({
            targets: result,
            y: result.y - 50,
            ease: 'Sine.Out',
            duration: floatTime,
            delay: 0,
            repeat: 0,
            yoyo: false,
            repeatDelay: 0,
            onComplete: finishAction
        });

        let killTimer = scene.time.addEvent({ 
            delay: floatTime + fadeTime, 
            callback: () => {
                result.destroy();
                emitter.stop();
                shadowEmitter.stop();
                if (dex === totalIcons - 1 && typeof whenFinished === "function"){
                    whenFinished();
                    return;
                }
            }, 
            callbackScope: scene 
        });
    })
}

export default Effect;