//eandebug: remember to add guards for zero and numbers greater than 9
//eandebug: remember to add guard for the case of the min number being higher than max
const Equation = (steps, type, operandMin, operandMax) => {
    let stepsTaken = 0;
    let nodes = [];
    for (let stepsTaken = 0; stepsTaken < steps; stepsTaken++){
        let num = Math.floor(Math.random() * operandMax);
        if (num < operandMin){
            num = operandMin
        }
        nodes.push(num);
        if (stepsTaken + 1 < steps){
            nodes.push(type);
        }
    }

    let answer = eval(nodes.join(" "))
    nodes.push("=");
    nodes.push(answer);

    return nodes;
}

export default Equation;