const Effect = (scene, gameObj, vert, horz) => {
    
    let amount = 20
    let vari = Math.random() > 0.5 ? -amount : amount;
    if (vert) {
        scene.tweens.add({
            targets: gameObj,
            y: gameObj.y - amount,
            ease: 'Sine.easeInOut',
            duration: 100,
            delay: 0,
            repeat: 0,
            yoyo: true,
            repeatDelay: 0,
        })
    }
    
    if (horz){
        scene.tweens.add({
            targets: gameObj,
            x: gameObj.x + vari,
            ease: 'Sine.easeInOut',
            duration: 20,
            delay: 0,
            repeat: 5,
            yoyo: true,
            repeatDelay: 0,
        })
    }
}

export default Effect;