import back from "src/assets/buttonBackground.png";



const button = (scene, x, y, character, call) => {
    let textData = {
        text: character,
        font: "retro",
        add: true,
        size: 25
    }
    let background = scene.add.image(0, 0, "buttonBackground");
    let text = scene.make.bitmapText(textData)
    let comp = scene.add.group();
    let mods = {};
    let xMod = 0;
    let widthMod = 1;


    background.tint = character === "?" ? 0x999999 : 0x6a0dad;

    if (typeof character === "number"){
        mods = modifySize(character);
        xMod = mods.x;
        widthMod = mods.width;
    }

    background.setScale(widthMod, 1)

    comp.add(background);
    comp.add(text);
    comp.setXY(x, y);
    comp.children.entries[1].x = (x - 14) + xMod;
    comp.children.entries[1].y = y - 15;

    background.setInteractive();
    background.on("pointerdown", () => {
        if (typeof call === "function"){
            call(character, comp);
        }
    }); 
    
    return comp
}

const modifySize = (num) => {
    let xMod = 0;
    let widthMod = 1;

    if (num < 9){
        
    }
    else if (num > 9 && num <= 99) {
        xMod = -12;
        widthMod = 1.5;
    }
    else if (num > 99 && num <= 999) {
        xMod = -30;
        widthMod = 2;
    }
    else if (num > 999 && num <= 9999) {
        xMod = -42;
        widthMod = 2.5;
    }
    else if (num > 9999 && num <= 99999) {
        xMod =  -56;
        widthMod = 3.25;
    }
    

    return {
        x: xMod,
        width: widthMod
    }
}

export default button;