
let Lifebar = (scene, player, width, height, totalTime, onTimeOver) => {
    let green  = 0x00ff00;
    let red    = 0xff0000;
    let yellow = 0xffff00;
    let remainingTime = totalTime;
    let gui = "block";

    let x = player.x - (width * 0.5);
    let y = player.y - 50;;
    // the energy container. A simple sprite
    // let energyContainer = scene.add.sprite(x, y, gui);
    // energyContainer.setDisplaySize(width, height);

    //energy bar shadow so it will contrast to container
    let energyBarShadow = scene.add.sprite(x, y, gui);
    energyBarShadow.setOrigin(0, 0.5);
    energyBarShadow.setDisplaySize(width, height); 
    energyBarShadow.tint = 0x555555;

    let energyBleed = scene.add.sprite(x, y, gui);
    energyBleed.setOrigin(0, 0.5);
    energyBleed.setDisplaySize(width, height);
    energyBleed.tint = red;


    // the energy bar. Another simple sprite
    let energyBar = scene.add.sprite(x, y, gui);
    energyBar.setOrigin(0, 0.5);
    energyBar.setDisplaySize(width, height);
    energyBar.tint = green;

    // a copy of the energy bar to be used as a mask. Another simple sprite but...
    let energyMask = scene.add.sprite(energyBar.x, energyBar.y, gui);
    energyMask.visible = false;
    energyMask.setOrigin(0, 0.5);
    energyMask.setDisplaySize(width, height);
    
    // and we assign it as energyBar's mask.
    energyBar.mask = new Phaser.Display.Masks.BitmapMask(scene, energyMask);

    //let stepWidth = energyMask.displayWidth / totalTime;

    // let gameTimer = scene.time.addEvent({
    //     delay: 1,
    //     callback:() => {
            
    //         if(remainingTime < 1){
    //             deactivate();
    //             return;
    //         }
    //         remainingTime --;           
    //         if(remainingTime < totalTime * 0.75 && remainingTime > totalTime *  0.25){
    //             energyBar.tint = yellow;
    //         }

    //         if(remainingTime < totalTime *  0.25){
    //             energyBar.tint = red;
    //         }
    //         // moving the mask
    //         energyMask.x += stepWidth;
            
    //     },
    //     callbackScope: scene,
    //     loop: true
    // });
    // let deactivate = () => {
    //     gameTimer.remove();
    //     if (typeof onTimeOver === "function"){
    //         onTimeOver(gameTimer);
    //     }        
    // }

    let life = scene.add.group();
    //life.add(energyContainer);
    life.add(energyBarShadow);
    life.add(energyBleed);
    life.add(energyBar);
    life.add(energyMask);

    player.on("hit", (newHealth) => {
        let quotient = newHealth / player._battleData.maxHealth;
        let newWidth = Math.max(0, width * quotient);

        energyBar.setDisplaySize(newWidth, height);
        let bleedAffect = scene.tweens.add({
            targets: energyBleed,
            duration: 3000,
            displayWidth: newWidth,
            delay: 0,
            repeat: 0,
        });

        let barFlash = scene.tweens.add({
            targets: energyBar,
            duration: 100,
            ease: "BounceInOut",
            tint: 0xffffff,
            yoyo: true,
            onComplete: () => {
                energyBar.tint = green;
            }
        });
        
    })
    return life;
}


export default Lifebar;