import TeamData from "src/tools/teamAlignmentData.js";

const characterDataBuilder = (scene, baseStats, teams, teamNumber) => {
    let play = {};
    play.name   = baseStats.name;
    play.pow    = baseStats.pow;
    play.maxHealth = baseStats.maxHealth;
    play.health    = baseStats.maxHealth;
    play.def    = baseStats.def;
    play.speed  = baseStats.speed;
    play.move   = baseStats.move;
    play.audioKeys = baseStats.sounds;
    play.atkType = baseStats.atkType;

    //status affects
    play = setStatusEffects(play);
    play = setStatusBuffs(play);

    //battle information
    play = setBattleData(play, teams, teamNumber);
    play.mainPlayer = !baseStats.cpu;
    play.turnTime = 0;
    play.skills = [
        "attack",
        "defend"
    ];

    //player media
    play.key = "SD"; //SS
    play.sprite = null;
    play.battleSounds = {};
    play.battleSounds = setSounds(play, scene);
    
    return play;
}

let setStatusEffects = (player) => {
    player.status = {
        alive: true,
        defending: false,
        defenseless: false,
        poisoned: false,
        protected: false
    }
    player.protectors = [];
    player.protectee = null;
    return player;
}

let setStatusBuffs = (player) => {
    player.statBuffs = {
        maxHealth: 0,
        pow: 0,
        def: 0,
        speed: 0,
    }
    return player;
}

let setSounds = (player, scene) => {
    player.audioKeys.forEach((sound) => {
        player.battleSounds[sound.type] = scene.sound.add(sound.data, {
            volume: sound.volume
        })
    })

    return player.battleSounds
}

let setBattleData = (player, teams, teamNumber) => {

    let myTeam = teams[teamNumber];
    let myTeamOrder = myTeam.length;
    let teamPosition = TeamData[teamNumber][myTeamOrder];

    player.team = teamNumber;
    player.directionFace = teamPosition[0];
    player.originX = teamPosition[1];
    player.originY = teamPosition[2];

    myTeam.push(player);
    return player;
}

export default characterDataBuilder;