const label = (scene, x, y, options, done) => {

    let comp = scene.add.group();
    let iter = 0;
    let opt = options[iter];
    let textData = {
        text: opt.name,
        font: "retro",
        add: true,
        size: 25
    }
    let background = scene.add.image(0, 0, "buttonBackground");
    let text = scene.make.bitmapText(textData);

    background.once("done", () => {
        done(opt)
    });
    background.tint = 0x6a0dad;
    background.setInteractive();
    background.setScale(9, 1);

    let xOffset = -200;
    let yOffset = - 15;
    text.x = x + xOffset;
    text.y = y + yOffset;
    background.x = x;
    background.y = y;

    let uiData = [
        0, 
        0, 
        "arrowUI"
    ];
    let uiCursor = scene.add.image(...uiData);
    uiCursor.angle = 90;
    uiCursor.setScale(2,2);
    uiCursor.alpha = 0;
    let pulseTween = scene.tweens.add({
        targets: uiCursor,
        displayWidth: uiCursor.displayWidth + 10,
        displayHeight: uiCursor.displayHeight + 10,
        ease: 'Bounce.InOut',
        duration: 50,
        repeat: -1,
        yoyo: true,
    });

    iter = setOption(options, iter, text, background, uiCursor, scene);

    let arrowYOffset = -100
    let arrowScale = 5;
    let upArrow = scene.add.image(x, y + arrowYOffset, "arrowUI");
    upArrow.angle = 270;
    upArrow.setScale(arrowScale, arrowScale);

    upArrow.setInteractive();
    upArrow.on("pointerdown", () => {
        iter = setOption(options, ++iter, text, background, uiCursor, scene)
    });

    let downArrow = scene.add.image(x, y - arrowYOffset, "arrowUI");
    downArrow.angle = 90;
    downArrow.setScale(arrowScale, arrowScale);

    downArrow.setInteractive();
    downArrow.on("pointerdown", () => {
        iter = setOption(options, --iter, text, background, uiCursor, scene)
    });

    comp.add(background);
    comp.add(text);
    comp.add(upArrow)
    comp.add(downArrow);
    comp.add(uiCursor);

    return comp
};

const setOption = (options, iter, textSprite, background, cursor, scene) => {
    if (iter > options.length - 1){
        iter = 0
    }

    if (iter < 0) {
        iter = options.length - 1;
    }
    let selection = options[iter];

    textSprite.text = selection.data.name;
    let width = selection.data.name.length;
    background.removeListener("pointerdown");
    background.on("pointerdown", () => {
        options.forEach((shell) => {
            shell.data.sprite.alpha = 1;
        });
        selection.action(selection);
        background.emit("done");
    });

    let inviscurse = () => {
        //cursor.alpha = 0;
    }

    cursor.alpha = 1;
    let sprite = selection.data.sprite;
    scene.tweens.add({
        targets: cursor,
        y: sprite.y - 75,
        x: sprite.x,
        ease: 'Sine.Out',
        duration: 250,
        delay: 0,
        repeat: 0,
        yoyo: false,
        repeatDelay: 0,
        onComplete: inviscurse
    });

    options.forEach((shell) => {
        shell.data.sprite.alpha = 0.25;
    });

    sprite.alpha = 1;
    return iter;
}

export default label;