import ProtectAlly from "src/battleSystem/protectAlly.js"

/**
 * @param {Object} scene reference to phaser 3 stage/state
 * @param {Object} stats - a struct with player battle data
 * @param {Object} targetStats - struct with victim battle data
 * @param {Array[boolean]} answers - array containing correct or incoorectg results of math puzzle
 * @param {*} onSequenceComplete - callback that occurs when player has returned to starting spot
 */
const attackSequence = (scene, stats, targetStats, answers, onSequenceComplete) => {
    let player = stats.sprite;
    let target = targetStats.sprite;
    let isProtected = targetStats.status.protected;
    let originalTarget = targetStats;

    let direction = "Right";
    let oppositeDirection = "Left";

    console.log("target is: ", targetStats, targetStats.status)
    if (isProtected) {
        console.log(targetStats.name, "is protected!")
        targetStats = ProtectAlly(targetStats);
        target = targetStats.sprite;
        let guardDistance = 50;
        target.y = originalTarget.sprite.y;
        if (!player.x > target.x) {
            guardDistance = -guardDistance;
        };
        target.x = originalTarget.sprite.x + guardDistance;
    }

    if (player.x > target.x){
        direction = "Left";
        oppositeDirection = "Right";
    }
    let hitDirection = direction === "Right" ? 1 : -1;


    player.once("engage", (answers, enemy, enemyStats) => {
        player.play("run" + direction + stats.key);
        scene.tweens.add({
            targets: player,
            x: enemy.x + (player.width + (player.width * 0.25)) * -hitDirection,
            y: enemy.y,
            ease: 'LinearIn', 
            duration: 1000,
            repeat: 0,
            onComplete: () => {
                player.emit("attack", answers, enemy, enemyStats)
            }
        });
    }, scene);

    player.once("attack", (answers, enemy, enemyStats) => {
        player.play(stats.atkType + direction + stats.key);
        stats.battleSounds.attack.play();
        answers.forEach((choice) => {
            if (choice){
                player.anims.chain(stats.atkType + direction + stats.key);
            }
        });
        player.anims.chain("run" + oppositeDirection + stats.key);
        player.on("animationstart-" + stats.atkType + direction + stats.key, () => {
            stats.battleSounds.attack.play();
        });
        player.on("animationcomplete-" + stats.atkType + direction + stats.key, () => {
            console.log(stats.pow, targetStats.def * 0.5)
            let damage = Math.max(1, stats.pow - ((targetStats.def * 0.5) + targetStats.statBuffs.def));
            damage = Math.ceil(damage);
            targetStats.health += -damage;
            enemy.emit("hit", targetStats.health);
            scene.hitText(enemy.x, enemy.y - 100, 40 * hitDirection, 0, -damage)
            scene.tweens.add({
                targets: enemy,
                x: enemy.x + (30 * hitDirection),
                duration: 30,
                yoyo: true,
                repeat: 0
            });

            if (targetStats.health < 1){
                targetStats.sprite.emit("fallen");
            }
        });

        player.once("animationstart-run" + oppositeDirection + stats.key, () => {
            player.emit("disengage", stats);
        });
    }, scene);

    player.once("disengage", (stats) => {
        player.removeListener("animationcomplete-" + stats.atkType + direction + stats.key);
        if (isProtected) {
            console.log(targetStats.name, "return to position")
            target.x = targetStats.originX;
            target.y = targetStats.originY;
        }
        
        scene.tweens.add({
            targets: player,
            x: stats.originX,
            y: stats.originY,
            ease: 'LinearIn', 
            duration: 500,
            repeat: 0,
            onComplete: () => {
                player.play("walk" + direction + stats.key);
                player.emit("walk" + direction + stats.key)
                if (typeof onSequenceComplete === "function"){
                    onSequenceComplete();
                }
            }
        });
    })

    console.log("attacker:" + stats.name + "\ntarget:" + targetStats.name)
    player.emit("engage", answers, target, targetStats);
}

export default attackSequence;