const selector = (scene, x, y, options, done) => {

    let comp = scene.add.group();
    let iter = 0;
    for (let skill in options){
        //let skill = options[o];
        let textData = {
            text: skill,
            font: "retro",
            add: true,
            size: 25
        }
        let background = scene.add.image(0, 0, "buttonBackground");
        let text = scene.make.bitmapText(textData)
    
        background.tint = 0x6a0dad;    
        background.setScale(5, 1);
        let xOffset = -100;
        let yOffset = background.height * iter;
        text.x = x + xOffset;
        text.y = y + yOffset;
        background.x = x;
        background.y = y + (yOffset + 15);

        comp.add(background);
        comp.add(text);
    
        background.setInteractive();
        background.on("pointerdown", () => {
            options[skill](skill, x, y);
            //send the chosen skill with "done" callback
            if (typeof done === "function"){
                done(skill)
            }
        });
        iter++;
    }
    return comp
}

