let defendEnd = (player) => {
    console.log("defense over!")
    player.defending = false;
    if (player.protectee !== null){
        for (let c = 0; c < player.protectee.protectors.length; c++){
            let character = player.protectee.protectors[c];
            if (player === character){
                player.protectee.protectors.splice(c, 1);
                break;
            }
        }
    }
    player.protectee = null;
    player.statBuffs.def = 0;
}

export default defendEnd;