//get game assets
import logoImg from "src/assets/logo.png";
import fontTexure from "src/assets/font/carrierCommand.png";
import fontXML from "src/assets/font/carrierCommand.xml";
import back from "src/assets/buttonBackground.png";
import block from "src/assets/whiteBlock.png";
import currentMark from "src/assets/grey_sliderDown.png";
import arrowUI from "src/assets/rightArrow.png";
import incorrectImg from "src/assets/grey_crossWhite.png";
import correctImg from "src/assets/grey_checkmarkWhite.png";

//audio
import backgroundMusic from "src/assets/wildWestCoastRacing.mp3";
import correctSound from "src/assets/correctSelect.mp3";
import incorrectSound from "src/assets/incorrectSelect.mp3"
import hit1 from "src/assets/hit1.mp3";
import hit2 from "src/assets/hit2.mp3";
import menuChoice1 from "src/assets/selectOption.mp3";


//modules
import SelectionUI from "src/tools/selectionUI.js";
import LabelSelectUI from "src/tools/labelSelectUI.js";
import CharacterBuild from "src/tools/characterDataBuilder.js";

//BattleModules
import DefendEnd from "src/battleSystem/defendEnd.js";

class Main extends Phaser.Scene {

    constructor () {
        super("main");
    }

    init(data) {}
    preload () {
        this.load.image("logo", logoImg);
        this.load.image("currentMark", currentMark);
        this.load.image("correctImg", correctImg);
        this.load.image("incorrectImg", incorrectImg);
        this.load.image("buttonBackground", back);
        this.load.image("block", block);
        this.load.image("arrowUI", arrowUI)
        this.load.bitmapFont("retro", fontTexure, fontXML);

        //load audio
        this.load.audio("correctAnswer", correctSound);
        this.load.audio("incorrectAnswer", incorrectSound);
        this.load.audio("hit1", hit1);
        this.load.audio("hit2", hit2);
        this.load.audio("menuChoice1", menuChoice1);
        this.load.audio("backgroundMusic", backgroundMusic);
    }
    create (data)  {
        let gameVolume = 0.3
        this.music = this.sound.add('backgroundMusic', {
            loop: true,
            volume: 0,
        });
        this.menuChoice1 = this.sound.add('menuChoice1', {
            volume: gameVolume - 0.25,
        });
        this.music.play({
            loop: true,
            volume: gameVolume
        });

        let teams = [
            [],
            []
        ]
        
        let p1t1 = CharacterBuild(this,
            {
                name: "Bunny G",
                pow: 20,
                maxHealth: 100,
                def: 20,
                speed: 50,
                atkType: "attack2",
                cpu: false,
                sounds: [
                    {
                        type: "attack",
                        data: "hit1",
                        volume: 1,
                    }
                ],
                move: "walk"
            },
            teams,
            0
        );

        let p2t1 = CharacterBuild(this,
            {
                name: "Ean",
                pow: 20,
                maxHealth: 100,
                def: 20,
                speed: 56,
                atkType: "attack2",
                cpu: false,
                sounds: [
                    {
                        type: "attack",
                        data: "hit1",
                        volume: 1,
                    }
                ],
                move: "walk"
            },
            teams,
            0
        )

        let p1t2 = CharacterBuild(this,
            {
                name: "Kill Tarboy",
                pow: 20,
                maxHealth: 100,
                def: 20,
                speed: 55,
                atkType: "attack2",
                sounds: [
                    {
                        type: "attack",
                        data: "hit1",
                        volume: 1,
                    }
                ],
                move: "walk",
                cpu: true
            },
            teams,
            1
        )
        
        let everyone = teams[0].concat(teams[1]);
        let battlePlug = this.scene.launch("battleTest",  {
            players: everyone
        });

        let battle = this.scene.get("battleTest");
        this.events.on("playerTurn", (player, battlers) => {
            this.playerTurn(player, battlers);
        });
    }

    playerTurn(player, battlers) {
        this.menuChoice1.play();
        let presentedSkills;
        let presentedTargets;
        
        if (player.status.defending){
            DefendEnd(player);
        }


        if (battlers.length < 2){
            console.log("There is no one to fight");
            return;
        }
        //Select Skill
        let selectedSkill = (skill, x, y) => {
            //console.log("selecting action!", skill)
        };
        let uiOptions = {};

        player.skills.forEach((skill) => {
            uiOptions[skill] = selectedSkill;
        })
        presentedSkills = SelectionUI(this, 400, 100, uiOptions, (action) => {
            this.events.emit("chooseTarget", action)
        });

        //Select Target
        this.events.once("chooseTarget", (action) => {
            this.menuChoice1.play();
            presentedSkills.setAlpha(0.25);
            let selectableBattlers = battlers.slice();
            let removeSelf = (self, allParticipants) => {
                let fallen = null;
                allParticipants.forEach((chosen, dex) => {
                    if (chosen === self){
                        fallen = selectableBattlers.splice(dex, 1);
                    }
                })
                console.log(fallen[0].name, "removed")
                return fallen;
            }
            let getSpecificTeam = (me, allParticipants) => {
                let newTeam = [];
                allParticipants.forEach((chosen) => {
                    if (chosen.team === me.team){
                        newTeam.push(chosen)
                    }
                });

                console.log(newTeam)
                return newTeam;
            }

            let iWantToAttack = action === "attack";
            let iWantToDefend = action === "defend";
            if (iWantToAttack){
                for (let id in battlers){
                    let participant = battlers[id];
                    let fallen = null
                    //player can't choose themselves
                    let itIsMe = participant === player;
                    let iAmDead = !participant.status.alive;                    
                    if (iWantToAttack && itIsMe || iAmDead){
                        removeSelf(participant, selectableBattlers);               
                    }
                }
            }

            if (iWantToDefend){
                selectableBattlers = getSpecificTeam(player, battlers)
            }
            console.log("selecteable battlers are:", selectableBattlers);
            let startPuzzle = (target) => {
                this.events.emit("launchPuzzle", action, target)
            }

            if (selectableBattlers.length === 0) {
                console.log("There is no one to battle!");
                return;
            }
            let participantUI = selectableBattlers.map((particpant) => {
                let participantNode = {
                    data: particpant,
                    action: startPuzzle,
                }
                return participantNode
            });

            presentedTargets = LabelSelectUI(this, 400, 150, participantUI, startPuzzle)
        })

        //Launch The Puzzle
        this.events.once("launchPuzzle", (action, target) => {
            this.menuChoice1.play();
            presentedSkills.destroy(true);
            presentedTargets.destroy(true);
            let puzzleData = {
                level: 3,
                time: 600
            }
            let puzzlePlugin = this.scene.launch("puzzle", puzzleData);
            let puzzle = this.scene.get("puzzle");
            puzzle.events.once("completed", (results) => {
                console.log("puzzle results are:", results, target);
                puzzle.scene.stop();
                let battle = this.scene.get("battleTest");
                battle.events.emit("action", action, [target.data], results)
            });
        });      
    }


    update(time, delta) {}

}

export default Main